    if (v?.max > 0 && v.value !== v.max) upd[`system.spells.${k}.value`] = v.max;
  }
  // re-assert pinned HP (catches Tough-style effects inflating max)
  const before = cur.system.attributes.hp.max;
  if (before !== PINNED_HP[name]) {
