const SKILLS = {
  "Bram Ironvow":     { prof: ["ath","itm"], exp: [] },
  "Skarn the Red":    { prof: ["ath","sur"], exp: [] },
  "Pip Locksley":     { prof: ["ste","slt","prc","acr"], exp: ["ste","slt"] },
