const acts = i => [...(i.system.activities ?? [])];
const atkOf = i => acts(i).find(a => a.type === "attack") ?? acts(i)[0];
const actType = i => atkOf(i)?.activation?.type ?? null;
// crude power score: biggest damage die x count, unarmed sinks to the bottom
const score = i => {
  if (/unarmed/i.test(i.name)) return -100;
  const parts = atkOf(i)?.damage?.parts ?? [];
  let best = 0;
  for (const p of parts) {
    const d = p.denomination ?? p.faces ?? 0, n = p.number ?? 1;
    best = Math.max(best, d * n);
  }
  const martial = /martial/i.test(i.system.type?.value ?? "") ? 1.5 : 0;
  const thrown = (i.system.properties?.has?.("thr") ?? false) ? -1 : 0;
  return best + martial + thrown;
};
const report = [];
for (const a of game.actors.filter(x => x.type === "character")) {
  const weapons = a.items.filter(i => i.type === "weapon");
  const action = weapons.filter(w => actType(w) === "action").sort((x,y) => score(y) - score(x));
  const bonus  = weapons.filter(w => actType(w) === "bonus").sort((x,y) => score(y) - score(x));
  const sets = {};
  for (let n = 0; n < 3; n++) sets[String(n+1)] = {
    primary: action[n]?.uuid ?? null, secondary: bonus[n]?.uuid ?? null
  };
  await a.setFlag("enhancedcombathud", "weaponSets", sets);
  report.push({actor: a.name, order: action.map(w => `${w.name}(${score(w)})`)});
}
return report;

