const report = [];
for (const scene of PLAN) {
  const fname = `SJ ${String(scene.n).padStart(2, "0")} — ${scene.name}`;
  let folder = game.folders.find(f => f.type === "Scene" && f.name === fname && f.folder?.id === root.id);
  if (!folder) folder = await Folder.create({ name: fname, type: "Scene", folder: root.id });

  const rows = [];
  for (let i = 0; i < scene.wants.length; i++) {
    const want = scene.wants[i];
    const hit = resolve(want);
    if (!hit) { rows.push({ want, status: "NOT FOUND" }); continue; }

    const already = game.scenes.find(s => s.folder?.id === folder.id && s.flags?.["space-journey-outline"]?.wanted === want);
    if (already) { rows.push({ want, status: "already imported", resolvedName: hit.entry.name }); continue; }

    const doc = await hit.pack.getDocument(hit.entry._id);
    const data = doc.toObject();
    delete data._id;
    data.name = `${i + 1}. ${hit.entry.name}`;
    data.folder = folder.id;
    data.navigation = false;
    data.flags = { ...(data.flags || {}), "space-journey-outline": { wanted: want, pack: hit.pack.collection } };
    const created = await Scene.create(data);
    rows.push({ want, status: `created (${hit.how})`, resolvedName: hit.entry.name, pack: hit.pack.collection });
  }
  report.push({ scene: fname, rows });
}

return report;

