const validActorUpdates = actorUpdates.filter(u => !u.error).map(({name, ...rest}) => rest);
await Actor.updateDocuments(validActorUpdates);

// 2) Per-token overrides on already-placed tokens (mook types cycle through their pool in placement order)
const sceneIds = ["ybhtwisDIVzStzYf","IhtEvDukRGFw08ZX","iZTAMcopIAEYjRZm","MQxWFiay97qVqxbQ","mGZnkMbexeRdNdkW","jyRC16PJqPmPKoyu","wXQv4IXwvidPTB5P","xABwEpluU6IOy43t","c2zdkZAoOJynvI31","8z9TyFZUyyiwgvRt","GW7y3wifH1UElKEn"];
const counters = {};
const tokenReport = [];
for (const sceneId of sceneIds) {
  const scene = game.scenes.get(sceneId);
  if (!scene) { tokenReport.push({sceneId, error: "not found"}); continue; }
  const updates = [];
  for (const token of scene.tokens.contents) {
    const actor = token.actor;
    if (!actor) continue;
    const name = actor.name;
    let path;
    if (variantPools[name]) {
      const idx = counters[name] || 0;
      path = variantPools[name][idx % variantPools[name].length];
      counters[name] = idx + 1;
    } else if (actorImg[name]) {
      path = actorImg[name];
    } else {
      continue;
    }
    updates.push({_id: token.id, "texture.src": IMG_BASE + path});
  }
  if (updates.length) await scene.updateEmbeddedDocuments("Token", updates);
  tokenReport.push({scene: scene.name, tokensUpdated: updates.length});
}

return {
  actorsUpdated: validActorUpdates.length,
  missingActors,
  tokenReport,
  totalTokensUpdated: tokenReport.reduce((s, r) => s + (r.tokensUpdated || 0), 0),
