    (byActor[t.actorId] ||= []).push(t);
  }

  const updates = [];
  for (const [name, coords] of Object.entries(actorMap)) {
    const actor = game.actors.getName(name);
    if (!actor) { results.push({sceneId, name, error: "actor not found"}); continue; }
    const toks = byActor[actor.id] || [];
    if (toks.length !== coords.length) {
      results.push({sceneId, name, warn: `token count ${toks.length} != coord count ${coords.length}`});
    }
    for (let i = 0; i < Math.min(toks.length, coords.length); i++) {
      const [ox, oy] = coords[i];
      updates.push({_id: toks[i].id, x: rect.x + ox, y: rect.y + oy});
    }
  }

  const isActive = (scene === canvas.scene);
  if (isActive) {
    // dodge the animation-lock bug: clear anims, then delete+recreate at target positions
    for (const t of scene.tokens.contents) {
      const p = canvas.tokens?.get(t.id);
      if (p) { if (p.stopAnimation) p.stopAnimation(); if (p.animationContexts) p.animationContexts.clear(); }
    }
    const posById = Object.fromEntries(updates.map(u => [u._id, u]));
    const specs = scene.tokens.contents.map(t => ({
      actorId: t.actorId, hidden: t.hidden, textureSrc: t.texture.src,
      x: posById[t.id]?.x ?? t.x, y: posById[t.id]?.y ?? t.y,
    }));
    await scene.deleteEmbeddedDocuments("Token", scene.tokens.contents.map(t => t.id));
    const toCreate = [];
    for (const spec of specs) {
      const actor = game.actors.get(spec.actorId);
      const td = await actor.getTokenDocument({x: spec.x, y: spec.y, hidden: spec.hidden});
      const obj = td.toObject();
      delete obj._id;
      obj.texture = { ...obj.texture, src: spec.textureSrc };
      toCreate.push(obj);
    }
    const created = await scene.createEmbeddedDocuments("Token", toCreate);
    results.push({scene: scene.name, method: "recreate", moved: created.length});
  } else {
    const res = await scene.updateEmbeddedDocuments("Token", updates, {diff: false});
    results.push({scene: scene.name, method: "update", moved: res.length});
  }
}
return results;

