const a = game.actors.get("PdADufxMREbGGCui");
const fom = a.items.getName("Font of Magic");
const results = {};
for (const n of ["Subtle Spell", "Twinned Spell"]) {
  const it = a.items.getName(n);
  const keep = {};
  for (const act of it.system.activities.values()) {
    const o = act.toObject ? act.toObject() : foundry.utils.deepClone(act);
    o.consumption = {
      ...o.consumption,
      targets: (o.consumption?.targets ?? []).map(t =>
        t.type === "itemUses" ? { ...t, target: fom.id } : t)
    };
    keep[o._id] = o;
  }
  await it.update({ "system.==activities": keep });
  results[n] = [...a.items.getName(n).system.activities.values()].map(act => ({
    targets: (act.consumption?.targets ?? []).map(t => ({ type: t.type, target: t.target, value: t.value })),
    resolvesTo: (act.consumption?.targets ?? []).map(t => a.items.get(t.target)?.name ?? "UNRESOLVED")
  }));
}
// sweep every other item for the same stale-compendium-target problem
const stale = [];
for (const it of a.items) {
  for (const act of it.system.activities?.values?.() ?? []) {
    for (const t of act.consumption?.targets ?? []) {
      if (t.type === "itemUses" && t.target && !a.items.get(t.target)) stale.push(`${it.name} → ${t.target}`);
    }
  }
}
return { fixed: results, remainingStaleTargets: stale };

