const hits = [];
for (const sheet of document.styleSheets) {
  let rules;
  try { rules = sheet.cssRules; } catch { continue; }
  for (const r of rules) {
    if (!r.selectorText || !r.style) continue;
    if (!r.style.transform && !r.style.getPropertyValue("transform")) continue;
    try { if (caret.matches(r.selectorText)) hits.push({
      selector: r.selectorText,
      transform: r.style.transform,
      priority: r.style.getPropertyPriority("transform"),
      href: (sheet.href || "inline").split("/").slice(-2).join("/")
    }); } catch {}
  }
}
return { matchingTransformRules: hits, computed: getComputedStyle(caret).transform };

