const header = `<p><em>115 candidate maps, every one with walls already drawn.</em> Each lives in the matching <strong>Suggestions</strong> sub-folder in the Scenes sidebar — open it, look, and delete what you don't want. Counts are <code>walls / lights</code>.</p>
<p>Sources, all already enabled in this world: <strong>Seafoot Maps</strong> (687 scenes, walls + lights + ambient sound), <strong>Eledryll Castle Life</strong>, <strong>Eledryll Spiders Tear Opera House</strong>, <strong>MAD Cartographer Wizard's Tower 1 &amp; 2</strong>, <strong>D&amp;D Dungeon Master's Guide</strong>. Nothing here is a raw image — the OneDrive battlemap folders and the 1,217 unnamed castle JPEGs were deliberately left out because they have no walls.</p>
<p><strong>Weakest match in the set:</strong> Greystone Granaries (folder 4). Nothing in the library is five interconnected warehouses around an ancient tower.</p>`;

const je = await JournalEntry.create({
  name: "Ardenford — Map Candidates",
  folder: jf.id,
  pages: [
    { name: "How to use this", type: "text", text: { content: header, format: 1 } },
    ...pages.map(([name, content]) => ({ name, type: "text", text: { content, format: 1 } })),
  ],
});
return { journal: je.name, folder: jf.name, pages: je.pages.size };

const je = game.journal.getName("Ardenford — Map Candidates");
const missing = je.pages.contents.filter(p => p.text.content?.includes("MISSING")).map(p => p.name);
return {
  world: game.world.id,
  missingRefs: missing,
  scenes: game.scenes.size,
  modulesActive: game.modules.filter(m => m.active).length,
  sceneFolders: game.folders.filter(f => f.type === "Scene").map(f => f.name),
  journalFolders: game.folders.filter(f => f.type === "JournalEntry").map(f => f.name),
};

const folders = game.folders.filter(f => f.type === "Compendium").map(f => ({ id: f.id, name: f.name, parent: f.folder?.id ?? null }));
const cfg = game.settings.get("core", "compendiumConfiguration");
return { folders, unfiled: game.packs.filter(p => !p.folder).map(p => p.collection), cfgKeys: Object.keys(cfg).length };

const cfg = foundry.utils.deepClone(game.settings.get("core", "compendiumConfiguration"));
cfg["pentaryn-seafoot-maps.scenes"] = { ...(cfg["pentaryn-seafoot-maps.scenes"] ?? {}), locked: false, folder: null };
await game.settings.set("core", "compendiumConfiguration", cfg);
return { seafoot: game.packs.get("pentaryn-seafoot-maps.scenes").locked };

const root = game.folders.find(f => f.name === "Suggestions" && f.type === "Scene");
const kids = game.folders.filter(f => f.folder?.id === root.id).sort((a,b) => a.name.localeCompare(b.name));
const sug = [];
const rows = kids.map(k => {
  const s = game.scenes.filter(x => x.folder?.id === k.id);
  s.forEach(x => sug.push(x));
  return { folder: k.name, scenes: s.length, minWalls: Math.min(...s.map(x => x.walls.size)) };
});
return {
  world: `${game.world.id} / ${game.world.title}`,
  modulesActive: game.modules.filter(m => m.active).length,
  lockRotation: game.settings.get("core", "prototypeTokenOverrides")?.npc?.lockRotation,
  rows,
  totalCandidates: sug.length,
  allWalled: sug.every(s => s.walls.size > 0),
  totalWalls: sug.reduce((n, s) => n + s.walls.size, 0),
  inNavBar: game.scenes.filter(s => s.navigation).map(s => s.name),
  activeScene: game.scenes.active?.name,
  journal: game.journal.getName("Ardenford — Map Candidates")?.pages.size + " pages",
};

const spec = [
