  allUsers: game.users.map(u => `${u.name} (role ${u.role}${u.isGM ? ", GM" : ""})`),
  roleNames: Object.fromEntries(Object.entries(CONST.USER_ROLES).map(([k, v]) => [v, k])),
};

const rows = [];
for (const u of game.users) {
  let ok = null;
  if (u.avatar) { try { ok = (await fetch("/" + u.avatar, { method: "HEAD" })).status; } catch (e) { ok = String(e); } }
  rows.push({ name: u.name, role: u.role, color: u._source.color, avatar: u.avatar, avatarHTTP: ok, password: u._source.password === "" ? "(none)" : "SET" });
}
const subj = ["jack-token-025881", "sean-token-af5f34", "zac-token-0e4a53"];
const subjOk = {};
for (const s of subj) subjOk[s] = (await fetch(`/assets/tokens/custom/ring-subjects/${s}.webp`, { method: "HEAD" })).status;
