};

const before = foundry.utils.deepClone(game.settings.get("core", "folderState") ?? {});
const state = game.settings.get("core", "folderState") ?? {};
const wanted = game.folders.filter(f => (f.type === "Scene" || f.type === "JournalEntry") && (f.name === "Suggestions" || f.name.match(/^[1-7] · /)));
for (const f of wanted) state[f.id] = true;
await game.settings.set("core", "folderState", state);
ui.scenes.render(true);
ui.journal.render(true);
return {
  expanded: wanted.map(f => `${f.type}: ${f.name}`),
  priorState: Object.keys(before).length,
  sceneTree: game.folders.filter(f => f.type === "Scene" && !f.folder).map(f => ({
    root: f.name,
    children: game.folders.filter(c => c.folder?.id === f.id).map(c => `${c.name} (${game.scenes.filter(s => s.folder?.id === c.id).length})`),
  })),
};

const out = {};
