    type: "character",
    img: s.art,
    ownership: { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.NONE, [u.id]: CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER },
    prototypeToken: {
