const out = [];
for (const n of want) {
  const e = p.index.find(i => i.name === n);
  if (!e) { out.push({ name: n, missing: true }); continue; }
  const d = await p.getDocument(e._id);
  out.push({ name: d.name, cr: d.system.details.cr, xp: d.system.details.xp?.value, hp: d.system.attributes.hp.max, ac: d.system.attributes.ac.value });
