const results = {}, missing = [];
for (const [sceneName, actorName, px, py, override] of plan) {
  const scene = game.scenes.getName(sceneName);
  const actor = game.actors.getName(actorName);
  if (!scene || !actor) { missing.push(`${sceneName} / ${actorName}`); continue; }
  const cx = px * S + OFF.x, cy = py * S + OFF.y;
  const td = await actor.getTokenDocument({
    x: Math.round((cx - G / 2) / G) * G,
    y: Math.round((cy - G / 2) / G) * G,
  });
  const o = td.toObject();
  if (override) o.name = override;
  const [tok] = await scene.createEmbeddedDocuments("Token", [o]);
  (results[sceneName] ??= []).push(`${tok.name} @ ${tok.x},${tok.y}`);
}
return {
  missing,
  perScene: Object.fromEntries(Object.entries(results).map(([k, v]) => [k, { count: v.length, tokens: v }])),
};

