for (const n of want) {
  let hit = null;
  for (const pid of packs) {
    const p = game.packs.get(pid); if (!p) continue;
    const e = p.index.find(i => i.name.toLowerCase() === n.toLowerCase());
    if (e) { hit = `Compendium.${pid}.Item.${e._id}`; break; }
