const kit = {
  "Wick Harlow":   { items: [U.Club, U.Lantern, U.Common, U.Pouch],
    lever: lever("Wick's Tally Board", "A porter's wax tally for Greystone crates. The counts do not match the manifest — one sack in forty, for eleven months. On the back, inked small and often re-inked: <em>Bryn</em>. Evidence against a consul's supplier and against Wick, in the same hand.") },
  "Sella Redcott": { items: [U.Dagger, U.Thieves, U.Travel, U.Pouch],
