    lever: lever("Bathhouse Keys", "Every door in the Vintara Baths on one ring, including the three private rooms and the canal dock nobody watches. She is not supposed to take them home. She does.") },
  "Aldric Dunwick": { items: [U.Dagger, U.Fine, U.Signet, U.InkPen],
    lever: lever("The Unsigned Writ", "A posting order in a clerk's hand, correct in every particular, with no name in the space where the issuing authority goes. Worth money to exactly one person and worth your life to another.") },
  "Brogmar-dur":   { items: [U.Warhammer, U.Lantern, U.Common, U.Tinderbox],
    lever: lever("The Favour Book", "No coin tab is kept at the Drowned Tap. This is kept instead: names, dates, and what was done. Brogmar decides what a favour is worth, and the book is why nobody argues.") },
  "Corr Ashgate":  { items: [U.Shortsword, U.Dagger, U.Thieves, U.Crowbar, U.Travel, U.Rope],
    lever: lever("Forged Reclamation Writ", "A Ruins Reclamation Act permit, well made — the seal is right, the wording is right, and the registry number belongs to an expedition that never came back. Good enough for a door clerk. Not good enough for Magister Merrick.") },
};

const report = [];
for (const [name, { items, lever: lv }] of Object.entries(kit)) {
  const a = game.actors.getName(name);
  if (!a) { report.push(`${name}: MISSING`); continue; }
  const data = [];
  for (const uuid of items) {
    const src = await fromUuid(uuid);
    if (!src) { report.push(`${name}: could not resolve ${uuid}`); continue; }
    const o = src.toObject();
    delete o._id;
    o.system.quantity = 1;
    o._stats = foundry.utils.mergeObject(o._stats ?? {}, { compendiumSource: uuid });
    data.push(o);
  }
  data.push(lv);
  const made = await a.createEmbeddedDocuments("Item", data);
  report.push(`${name}: ${made.map(i => i.name).join(", ")}`);
}
return report;

